func TestSkippedUpstreamTwins(t *testing.T) {
	if len(skippedTwins) == 0 {
		t.Fatal("no skipped twins listed")
	}
	for _, c := range skippedTwins {
		t.Run(c.File+":"+itoaInt(c.Line), func(t *testing.T) { t.Skip(c.Name + " -- " + c.Reason) })
	}
}
